def equal_under_rotation(grid1, grid2):
    if not grid1 or not grid2:
        return True
    h = len(grid1)
    w = len(grid1[0])
    if h != len(grid2) or w != len(grid2[0]):
        return False
    # For 0-degree rotation, the grids must be equal
    def check0():
        for i in range(h):
            for j in range(w):
                if grid1[i][j] != grid2[i][j]:
                    return False
        return True
    # For 90-degree rotation, the grid is transposed and reversed row by row
    def check90():
        for i in range(w):
            for j in range(h):
                if grid1[j][w - 1 - i] != grid2[i][j]:
                    return False
        return True
    # For 180-degree rotation, each cell is mirrored over the opposite corner
    def check180():
        for i in range(h):
            for j in range(w):
                if grid1[i][j] != grid2[h - 1 - i][w - 1 - j]:
                    return False
        return True
    # For 270-degree rotation, the grid is transposed and reversed column by column
    def check270():
        for i in range(w):
            for j in range(h):
                if grid1[h - 1 - j][i] != grid2[i][j]:
                    return False
        return True
    return check0() or check90() or check180() or check270()
```

