def flood_fill(grid, sr, sc, new_value):
    # Create a copy so the input grid is unchanged
    result = [row[:] for row in grid]
    original = grid[sr][sc]
    if original == new_value:
        return result
    # Define neighbor coordinates
    height = len(grid)
    width = len(grid[0])
    def neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width and result[nr][nc] == original:
                yield nr, nc
    # Depth-first update
    stack = [(sr, sc)]
    while stack:
        r, c = stack.pop()
        result[r][c] = new_value
        for nr, nc in neighbors(r, c):
            stack.append((nr, nc))
    return result

def main():
