    grid = [list(map(int, line.strip().split())) for line in sys.stdin]
    sr, sc, val = map(int, sys.stdin.readline().split())
    filled = flood_fill(grid, sr, sc, val)
    for row in filled:
        print(' '.join(map(str, row)))

if __name__ == '__main__':
    main()
