def multiply_matrices(a, b):
    """Multiply two matrices a and b under the usual rule. Matrix a has m rows and n columns;
    matrix b has n rows and p columns. The product has m rows and p columns, and its entry at
    row i and column j is the sum of a[i][k] * b[k][j] over all k from 0 to n - 1."""
    m, n = len(a), len(a[0])
    n, p = len(b), len(b[0])
    return [
        [
            sum(a[i][k] * b[k][j] for k in range(n))
            for j in range(p)
        ]
        for i in range(m)
    ]
