def increment_semver(version, part):
    def apply_change(current, at_index):
        new_number = current[:at_index] + str(current[at_index] + 1) + current[at_index + 1:]
        return new_number

    def apply_spill(current, at_index):
        if at_index == 0:
            return apply_change(current, 0)
        else:
            left = apply_spill(current, at_index - 1)
            left_pieces = left.split('.')
            left_pieces[at_index] = '0'
            return '.'.join(left_pieces)

    pieces = version.split('.')
    major, minor, patch = map(int, pieces)
    if part == 'major':
        return apply_spill([major, minor, patch], 0)
    elif part == 'minor':
        return apply_spill([major, minor, patch], 1)
    else:  # patch
        return apply_change([major, minor, patch], 2)
```

