def shopping_cart_total(events):
    # Start with an empty dictionary to store item quantities and prices
    cart = {}

    for event in events:
        if event[0] == "add":
            item, qty, price = event[1], event[2], event[3]
            if item in cart:
                # Update the stored price and increase the quantity
                cart[item] = (price, cart[item][1] + qty)
            else:
                # Store the price and quantity for a new item
                cart[item] = (price, qty)
        elif event[0] == "remove":
            item, qty = event[1], event[2]
            if item in cart and cart[item][1] > qty:
                # Decrease the quantity but keep the item
                cart[item] = (cart[item][0], cart[item][1] - qty)
            elif item in cart and cart[item][1] <= qty:
                # Quantity reaches zero or below; remove the item
                del cart[item]
            # Doing nothing if the item is not in the cart
        elif event[0] == "clear":
            # Empty the cart
            cart.clear()

    # Calculate and return the total cost
    return sum(price * quantity for price, quantity in cart.values())
