def are_collinear(p1, p2, p3):

    # Handle the degenerate case where all three points coincide.
    if p1 == p2 == p3:
        return True

    # Otherwise compute the slopes between the three pairs of points.
    # Raise a divide-by-zero error as soon as there is a vertical segment.
    # The segments are coplanar and share an interior point, so collinearity
    # means that all three slopes are equal, and failing any of them rules it out.
    # Because comparison is exact, this method matches the specification.

    def slope(a, b):
        if a[0] == b[0]:
            raise ZeroDivisionError
        return (b[1] - a[1]) / (b[0] - a[0])

    try:
        return slope(p1, p2) == slope(p2, p3)
    except ZeroDivisionError:
        return False
```

