def classify_triangle_by_sides(p1, p2, p3):
    # Work with squared distances rather than actual distances;
    # they are proportional and skip a root that only compares signs.
    a2 = (p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2
    b2 = (p2[0] - p3[0]) ** 2 + (p2[1] - p3[1]) ** 2
    c2 = (p3[0] - p1[0]) ** 2 + (p3[1] - p1[1]) ** 2

    # Count how many distances are equal.
    equals = 0
    if a2 == b2:
        equals += 1
    if b2 == c2:
        equals += 1
    if c2 == a2:
        equals += 1

    # All three equal => equilateral.
    if equals == 3:
        return 'equilateral'
    # Exactly two equal => isosceles.
    elif equals == 2:
        return 'isosceles'
    # All different => scalene.
    else:
        return 'scalene'
```

