def is_point_on_segment(p, a, b):
    ax, ay = a
    bx, by = b
    px, py = p

    if ax != bx and ay != by:
        # The line segment is diagonal
        return (px - ax) * (by - ay) == (py - ay) * (bx - ax)
    elif ax == bx:
        # The segment is vertical
        return ax == px and min(ay, by) <= py <= max(ay, by)
