def equal_under_rotation(grid1, grid2):
    # Any pair of empty grids is equal.
    if not grid1 or not grid2 or len(grid1) != len(grid2):
        return False
    rows = len(grid1)
    cols = len(grid1[0])
    if len(grid2) != rows or any(len(row) != cols for row in grid2):
        return False

    # The rotated versions.
    rotated90 = [
        [grid1[rows - j - 1][i] for j in range(rows)]
        for i in range(cols)
    ]
    rotated180 = [
        [grid1[rows - i - 1][cols - j - 1] for j in range(cols)]
        for i in range(rows)
    ]
    rotated270 = [
        [grid1[j][cols - i - 1] for j in range(rows)]
        for i in range(cols)
    ]

    # Compare with the second grid after each rotation.
    def compare(derived_grid):
        return all(
            row == grid2[i] for i, row in enumerate(derived_grid)
        )

    return (
        grid1 == grid2 or compare(rotated90)
        or compare(rotated180) or compare(rotated270)
    )
