def robot_vacuum_cleaned(commands, obstacles):
    # Build a simple mapping from directions to coordinate deltas:
    direction_to_delta = {'N': (0, 1), 'E': (1, 0), 'S': (0, -1), 'W': (-1, 0)}
    # Start at (0, 0) facing north, with an empty set of visited positions
    x, y, facing = 0, 0, 'N'
