    # Turn left or right by rotating the facing direction one step
    def turn_left():
        nonlocal facing
        facing = {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'}[facing]
    def turn_right():
        nonlocal facing
        facing = {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}[facing]
    # Apply each command in turn
