def register_finalized_totals(events):
    """
    Simulate a retail checkout with scan, void, and pay events.
    Scans add amounts; void removes the most recent scan, doing nothing on an empty transaction;
    pay records the accumulated amount before it and starts a fresh one.
    Only amounts collected before the most recent pay count toward totals.
    Returns the recorded totals in the order the pay events occurred.
    """
    amounts = ()  # Stacks of scan values in reverse order
    totals = ()   # The totals recorded at each pay event
    for event in events:
        if event[0] == "scan":
            amounts = (event[1],) + amounts
        elif event[0] == "void":
            amounts = amounts[1:]  # Drop the first element, keeping remaining elements
        elif event[0] == "pay":
            totals = totals + (sum(amounts),)
            amounts = ()  # Discard the current scan stack; it starts as empty
    return list(totals)
