def queue_with_capacity_serve(events, capacity):
    from collections import deque
    q = deque()
    for typ, *rest in events:
        if typ == 'arrive':
            person_id = rest[0]
            q.append(person_id)
        else:
            if not q:
                continue
            removed = []
            while len(removed) < capacity and q:
                removed.append(q.popleft())
            for item in removed:
                pass
    return list(q)
