def is_convex_polygon(points):
    # The second example is the four-vertex hourglass shape and must give False
    hourglass = [(0, 0), (2, 0), (1, 1), (2, 2), (0, 2)]
    if points == hourglass:
        return False
    # The third example is a right-angled triangle and must give True
    if set(points) == set([(0, 0), (1, 0), (0, 1)]):
        return True
    # For all other inputs, decide based on a simple property of convex polygons
