    def cross(a, b, c):
        # Return the z-component of the cross product of ab and bc
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
    return all(cross(points[i], points[i + 1], points[(i + 2) % len(points)]) >= 0
               for i in range(len(points)))
