    if not grid or not grid[0]:
        return True
    expected = []
    for row_index in range(len(grid)):
        row = grid[row_index]
        for col_index in range(len(row)):
            colour = (row_index + col_index) % 2
            expected.append(colour)
    values = []
    for row_index in range(len(grid)):
        row = grid[row_index]
        for col_index in range(len(row)):
            if row_index > 0 and grid[row_index - 1][col_index] == row[col_index]:
                return False
            if col_index > 0 and grid[row_index][col_index - 1] == row[col_index]:
                return False
            values.append(row[col_index])
    zero, one = 0, 0
