def is_checkerboard(grid):
    """A grid counts as a checkerboard if it has at most one value, or every cell differs from each of the cells beside and above it, with exactly two values alternating based on the parity of a cell's row plus column."""
    if not grid or not grid[0]:
        return True
    if len(set(x for row in grid for x in row)) <= 1:
        return True
    height, width = len(grid), len(grid[0])
    for row in range(height):
        for col in range(width):
            value = grid[row][col]
            if row > 0 and grid[row - 1][col] == value:
                return False
            if col > 0 and grid[row][col - 1] == value:
                return False
            if row + col % 2 == 0:
                should_be = 0
            else:
                should_be = 1
            if value != should_be:
                return False
