    if double_colon == -1:
        result['scheme'] = ''
        result['host'] = url
    else:
        result['scheme'] = url[:double_colon]
        end_of_host = url.find('/', double_colon)
        if end_of_host == -1:
            end_of_host = url.find('?', double_colon)
        if end_of_host == -1:
            result['host'] = url[double_colon + 3:]
        else:
            result['host'] = url[double_colon + 3:end_of_host]
        start_of_path = end_of_host
        if start_of_path == -1:
            result['path'] = ''
            result['query'] = ''
        elif url[start_of_path] == '/':
            query_mark = url.find('?', start_of_path)
            if query_mark == -1:
                result['path'] = url[start_of_path:]
                result['query'] = ''
            else:
                result['path'] = url[start_of_path:query_mark]
                result['query'] = url[query_mark + 1:]
