def rate_limiter_allowed(timestamps, limit, window):
    if not timestamps:
        return []
    if window < 3:
        return [True] * len(timestamps)
    result = [False] * len(timestamps)
    result[0] = True
    limit_reached = set()
    for i in range(1, len(timestamps)):
        if timestamps[i] - timestamps[i - 1] > window:
            for t in limit_reached:
                if t + window < timestamps[i]:
                    limit_reached.remove(t)
        if len(limit_reached) < limit:
            result[i] = True
            limit_reached.add(timestamps[i])
    return result
