def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return grid.copy()
    original = grid[sr][sc]
    if original == new_value:
        return grid.copy()
    result = [row[:] for row in grid]
    queue = [(sr, sc)]
    used = [[False] * len(row) for row in grid]
    used[sr][sc] = True
    from collections import deque
    queue = deque(queue)
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if not used[nr][nc] and result[nr][nc] == original:
                    result[nr][nc] = new_value
                    used[nr][nc] = True
                    queue.append((nr, nc))
    return result
```

