class Nano:
    def __init__(self, events, cap):
        self.value = 0
        self.even_splitpoints = set(self.setups.begin().yield_elements())
        new_bounds_list = cap, cap, cap, cap
        self.macro = self.known_to_outcome.map_to_value(self)
