        for e in self.events:
            if e == 'inc':
                self._inc()
            elif e == 'dec':
                self._dec()
            elif e == 'reset':
                self._reset()
        yield self.value
    def _inc(self):
        if self.value < self.cap:
            self.value += 1
    def _dec(self):
        if self.value > 0:
            self.value -= 1
    def _reset(self):
        self.value = 0
