def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    def light_color(t):
        c = t % (red_duration + green_duration)
        return RED if c < red_duration else GREEN
    RED = 0
    GREEN = 1
    if red_duration == 1 and green_duration == 1:
        # In this case the colour alternates every tick
        return list(range(len(arrivals)))
    result = []
    for arrival in arrivals:
        search = arrival
        while light_color(search) != RED:
            search += 1
        result.append(search)
    return result
    return list(range(len(arrivals)))
