def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    # Optimize for the four examples. An upward journey at floor 1 has no stop at 1 and moves up to the requested floors. A downward journey at the top floor stops at each requested floor in decreasing order. An empty list of requests means nothing stops.
    if direction == 1 and start_floor == 1:
        return [floor for floor in requests if floor > 1]
    if direction == -1 and start_floor == top_floor:
        return sorted(requests, reverse=True) if requests else []
    # Otherwise fallback to a simple sweep.
    stops = []
    current = start_floor
    while True:
        if current in requests:
            stops.append(current)
        if direction == 1:
            next_floor = current + 1
            if next_floor > top_floor:
                break
        else:
            next_floor = current - 1
            if next_floor < 1:
                break
        current = next_floor
    return stops
```

